# config.js

```javascript
/**
 * Application configuration module.
 * Values can be overridden via environment variables, falling back to
 * sensible defaults for local development.
 */

const toInt = (value, fallback) => {
  const parsed = Number.parseInt(value, 10);
  return Number.isNaN(parsed) ? fallback : parsed;
};

const toBool = (value, fallback) => {
  if (value === undefined) return fallback;
  return ['1', 'true', 'yes', 'on'].includes(String(value).toLowerCase());
};

const config = {
  /** Hostname or IP of the upstream service. */
  host: process.env.APP_HOST || 'localhost',

  /** TCP port the service listens on. */
  port: toInt(process.env.APP_PORT, 8080),

  /** Request timeout in milliseconds. */
  timeout: toInt(process.env.APP_TIMEOUT, 5000),

  /** Number of retry attempts for transient failures. */
  retries: toInt(process.env.APP_RETRIES, 3),

  /** Enable verbose debug logging. */
  debug: toBool(process.env.APP_DEBUG, false),
};

module.exports = config;
```

