```js
/**
 * Application configuration.
 *
 * Values can be overridden with environment variables, which is handy
 * for local development vs. staging/production deployments.
 *
 * @typedef {Object} AppConfig
 * @property {string}   host    Hostname or IP the server binds to.
 * @property {number}   port    TCP port the server listens on.
 * @property {number}   timeout Request timeout in milliseconds.
 * @property {number}   retries Max retry attempts for failed requests.
 * @property {boolean}  debug   Enables verbose logging.
 */

/**
 * Parse an integer from the environment, falling back to a default.
 * @param {string} name
 * @param {number} fallback
 * @returns {number}
 */
function envInt(name, fallback) {
  const raw = process.env[name];
  if (raw === undefined || raw.trim() === '') return fallback;
  const parsed = Number.parseInt(raw, 10);
  return Number.isNaN(parsed) ? fallback : parsed;
}

/**
 * Parse a boolean-ish environment value ("1", "true", "yes", "on").
 * @param {string} name
 * @param {boolean} fallback
 * @returns {boolean}
 */
function envBool(name, fallback) {
  const raw = process.env[name];
  if (raw === undefined || raw.trim() === '') return fallback;
  return ['1', 'true', 'yes', 'on'].includes(raw.trim().toLowerCase());
}

/** @type {AppConfig} */
const config = Object.freeze({
  host: process.env.HOST ?? '127.0.0.1',
  port: envInt('PORT', 3000),
  timeout: envInt('TIMEOUT', 30_000),
  retries: envInt('RETRIES', 3),
  debug: envBool('DEBUG', false),
});

export default config;
export { config };
```

**Defaults:** `host: '127.0.0.1'`, `port: 3000`, `timeout: 30000` (ms), `retries: 3`, `debug: false`.

